const languageIndex: Record<Language, number> = { en: 0, fr: 1, es: 2, de: 3, zh: 4, ar: 5 };
const translationsByText = new Map(rows.map(row => [row[0], row]));
const legacyKeyByText = new Map<string, keyof Translations>();

(Object.keys(translations.en) as (keyof Translations)[]).forEach(key => {
  legacyKeyByText.set(translations.en[key], key);
});

export function translateText(text: string, language: Language): string {
  const row = translationsByText.get(text);
  if (row) return row[languageIndex[language]];
  const legacyKey = legacyKeyByText.get(text);
  return legacyKey ? translations[language][legacyKey] : text;
}
